-- Every synthetic identity, membership and fee is isolated and rolls back.
BEGIN;
DO $test$
DECLARE actor uuid:='21200000-0000-4000-8000-000000000001';op uuid:='21200000-0000-4000-8000-000000000002';store uuid:='21200000-0000-4000-8000-000000000003';member uuid:='21200000-0000-4000-8000-000000000004';attempt uuid:='21200000-0000-4000-8000-000000000005';plan uuid;token text;invitation uuid;principal uuid;r jsonb;stores_before bigint;workflows_before bigint;features jsonb:='{"catalog":true,"orders":true,"customers":true,"content":true,"media":true,"analytics":true,"checkout":true,"custom_domains":true,"staff_management":true,"promotions":true,"integrations":true,"accounting":true,"marketplaces":true}';limits jsonb:='{"products":1000000,"staff":1000000,"storageBytes":9007199254740991,"monthlyOrders":1000000,"customDomains":1000000}';
BEGIN
 IF to_regprocedure('saas.platform_invitation_create(uuid,jsonb,bigint,text,text)') IS NULL THEN RAISE EXCEPTION 'PLATFORM_INVITATION_FUNCTION_MISSING';END IF;
 IF has_function_privilege('public','saas.platform_invitation_complete(uuid,text,text,text,boolean)','EXECUTE') OR has_function_privilege('celebix_saas_app','saas.platform_invitation_complete(uuid,text,text,text,boolean)','EXECUTE') OR has_function_privilege('celebix_saas_platform_operator','saas.platform_invitation_complete(uuid,text,text,text,boolean)','EXECUTE') THEN RAISE EXCEPTION 'UNVERIFIED_INVITATION_ENTRY_EXPOSED';END IF;
 INSERT INTO saas.principals(id,issuer,subject,email,email_verified,created_at,updated_at) VALUES(actor,'https://fixture212.invalid','operator212','sdkahmetcelebi@icloud.com',true,now(),now());
 INSERT INTO saas.platform_operators(id,issuer,subject,principal_id,email,active) VALUES(op,'https://fixture212.invalid','operator212',actor,'sdkahmetcelebi@icloud.com',true);
 INSERT INTO saas.stores(id,name,slug,status,locale,currency,theme_key,created_at,updated_at) VALUES(store,'Invitation fixture','invitation-fixture-212','active','tr','TRY','base',now(),now());
 INSERT INTO saas.memberships(id,principal_id,store_id,role,status,created_at,updated_at) VALUES(member,actor,store,'store_owner','active',now(),now());
 INSERT INTO saas.admin_domains(id,store_id,hostname,kind,status,canonical,verified_at,created_at,updated_at,management) VALUES(gen_random_uuid(),store,'invitation212.admin.example.test','platform_subdomain','active',true,now(),now(),now(),'platform');
 r:=saas.platform_command(op,'plan.publish',jsonb_build_object('code','platform_native_212','features',features,'limits',limits),0,'fixture-plan-212');plan:=(r#>>'{result,planId}')::uuid;
 PERFORM saas.platform_command(op,'subscription.assign',jsonb_build_object('storeId',store,'planId',plan),0,'fixture-assign-212');
 INSERT INTO saas.principals(id,issuer,subject,email,email_verified,created_at,updated_at) VALUES(gen_random_uuid(),'https://foreign212.invalid','foreign212','new212@example.test',true,now(),now());
 stores_before:=(SELECT count(*) FROM saas.stores);workflows_before:=(SELECT count(*) FROM saas.registration_workflows);
 r:=saas.platform_invitation_create(op,jsonb_build_object('storeId',store,'targetEmail','new212@example.test','role','admin','kind','invite'),1,'new-invite-212','https://fixture212.invalid');token:=r#>>'{result,acceptanceToken}';invitation:=(r#>>'{result,invitationId}')::uuid;
 IF jsonb_array_length(saas.platform_invitation_read(op,jsonb_build_object('storeId',store,'email','new212@example.test'),'https://fixture212.invalid')->'candidates')<>0 THEN RAISE EXCEPTION 'FOREIGN_ISSUER_CANDIDATE_EXPOSED';END IF;
 IF (SELECT target_principal_id FROM saas.platform_member_invitations WHERE id=invitation) IS NOT NULL OR EXISTS(SELECT 1 FROM saas.principals WHERE issuer='https://fixture212.invalid' AND email='new212@example.test') THEN RAISE EXCEPTION 'UNVERIFIED_INVITEE_ACTIVATED_EARLY';END IF;
 r:=saas.platform_invitation_create(op,jsonb_build_object('storeId',store,'targetEmail','new212@example.test','role','admin','kind','invite'),1,'new-invite-212','https://fixture212.invalid');IF r->>'outcome'<>'replayed' OR r#>>'{result,acceptanceToken}'<>token THEN RAISE EXCEPTION 'INVITE_REPLAY_CHANGED';END IF;
 BEGIN PERFORM saas.platform_command(op,'sales.pause',jsonb_build_object('storeId',store,'reason','global key collision'),1,'new-invite-212');RAISE EXCEPTION 'INVITE_GLOBAL_KEY_COLLISION_ALLOWED';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'operation_mismatch' THEN RAISE;END IF;END;
 BEGIN PERFORM saas.platform_invitation_start(attempt,token,'wrong.admin.example.test',repeat('a',64),repeat('b',64),'{}',clock_timestamp()+interval '5 minutes');RAISE EXCEPTION 'WRONG_INVITE_HOST_ALLOWED';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'invitation_denied' THEN RAISE;END IF;END;
 PERFORM saas.platform_invitation_start(attempt,token,'invitation212.admin.example.test',repeat('a',64),repeat('b',64),'{"encryptedFixture":true}',clock_timestamp()+interval '5 minutes');
 BEGIN PERFORM saas.platform_invitation_claim(repeat('a',64),repeat('c',64));RAISE EXCEPTION 'WRONG_BROWSER_BINDING_ALLOWED';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'invitation_denied' THEN RAISE;END IF;END;
 r:=saas.platform_invitation_claim(repeat('a',64),repeat('b',64));IF r->>'outcome'<>'claimed' THEN RAISE EXCEPTION 'CLAIM_FAILED';END IF;
 BEGIN PERFORM saas.platform_invitation_complete(attempt,'https://fixture212.invalid','new212','new212@example.test',false);RAISE EXCEPTION 'UNVERIFIED_EMAIL_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'verified_identity_required' THEN RAISE;END IF;END;
 BEGIN PERFORM saas.platform_invitation_complete(attempt,'https://foreign212.invalid','foreign212','new212@example.test',true);RAISE EXCEPTION 'WRONG_ISSUER_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'invitation_denied' THEN RAISE;END IF;END;
 BEGIN PERFORM saas.platform_invitation_complete(attempt,'https://fixture212.invalid','wrong212','wrong212@example.test',true);RAISE EXCEPTION 'WRONG_EMAIL_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'invitation_denied' THEN RAISE;END IF;END;
 r:=saas.platform_invitation_complete(attempt,'https://fixture212.invalid','new212','new212@example.test',true);
 SELECT id INTO principal FROM saas.principals WHERE issuer='https://fixture212.invalid' AND subject='new212';
 IF r->>'outcome'<>'committed' OR principal IS NULL OR NOT EXISTS(SELECT 1 FROM saas.memberships WHERE store_id=store AND principal_id=principal AND role='admin' AND status='active' AND support_session_id IS NULL) OR (SELECT count(*) FROM saas.stores)<>stores_before THEN RAISE EXCEPTION 'NEW_IDENTITY_MEMBERSHIP_OR_STORE_COUNT_INVALID';END IF;
 IF jsonb_array_length(saas.platform_invitation_read(op,jsonb_build_object('storeId',store,'email','new212@example.test'),'https://fixture212.invalid')->'candidates')<>1 OR jsonb_array_length(saas.platform_invitation_read(op,jsonb_build_object('storeId','21200000-0000-4000-8000-000000000099'),'https://fixture212.invalid')->'items')<>0 THEN RAISE EXCEPTION 'INVITATION_CANDIDATE_OR_TENANT_SEPARATION_INVALID';END IF;
 r:=saas.platform_invitation_claim(repeat('a',64),repeat('b',64));IF r->>'outcome'<>'replayed' OR r#>>'{result,redirectUrl}'<>'https://invitation212.admin.example.test/invitations/accepted' THEN RAISE EXCEPTION 'CALLBACK_REPLAY_RESULT_INVALID';END IF;
 BEGIN PERFORM saas.platform_invitation_complete(attempt,'https://fixture212.invalid','different212','new212@example.test',true);RAISE EXCEPTION 'FROZEN_SUBJECT_CHANGED_ON_REPLAY';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'invitation_denied' THEN RAISE;END IF;END;
 r:=saas.platform_invitation_create(op,jsonb_build_object('storeId',store,'targetEmail','new212@example.test','targetPrincipalId',principal,'role','store_owner','kind','transfer','previousOwnerDisposition','admin'),3,'transfer-invite-212','https://fixture212.invalid');token:=r#>>'{result,acceptanceToken}';attempt:='21200000-0000-4000-8000-000000000006';
 PERFORM saas.platform_invitation_start(attempt,token,'invitation212.admin.example.test',repeat('d',64),repeat('e',64),'{}',clock_timestamp()+interval '5 minutes');PERFORM saas.platform_invitation_claim(repeat('d',64),repeat('e',64));
 r:=saas.platform_invitation_complete(attempt,'https://fixture212.invalid','new212','new212@example.test',true);
 IF NOT EXISTS(SELECT 1 FROM saas.memberships WHERE store_id=store AND principal_id=principal AND role='store_owner' AND status='active') OR NOT EXISTS(SELECT 1 FROM saas.memberships WHERE id=member AND role='admin' AND status='active') OR (SELECT count(*) FROM saas.stores)<>stores_before THEN RAISE EXCEPTION 'OWNER_TRANSFER_OR_STORE_CREATION_INVALID';END IF;
 BEGIN UPDATE saas.memberships SET status='revoked' WHERE store_id=store AND role='store_owner';RAISE EXCEPTION 'LAST_OWNER_REMOVED_BY_INVITATION';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'last_owner' THEN RAISE;END IF;END;
 r:=saas.platform_invitation_create(op,jsonb_build_object('storeId',store,'targetEmail','expired212@example.test','role','editor','kind','invite'),5,'expired-invite-212','https://fixture212.invalid');token:=r#>>'{result,acceptanceToken}';attempt:='21200000-0000-4000-8000-000000000007';PERFORM saas.platform_invitation_start(attempt,token,'invitation212.admin.example.test',repeat('f',64),repeat('0',64),'{}',clock_timestamp()+interval '1 minute');UPDATE saas.platform_invitation_oidc_attempts SET expires_at=clock_timestamp()-interval '1 second' WHERE id=attempt;
 BEGIN PERFORM saas.platform_invitation_claim(repeat('f',64),repeat('0',64));RAISE EXCEPTION 'EXPIRED_CALLBACK_ALLOWED';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'invitation_denied' THEN RAISE;END IF;END;
 IF (SELECT count(*) FROM saas.registration_workflows)<>workflows_before THEN RAISE EXCEPTION 'INVITE_CREATED_REGISTRATION_WORKFLOW';END IF;
 RAISE NOTICE 'SQL212 PASS: new verified principal→membership only, unchanged store count, host/browser/verified email/immutable identity/expiry gates, replay, global key, atomic owner transfer and last-owner guard';
END $test$;
ROLLBACK;
